package com.mealmate.payment; import jakarta.persistence.*; import java.util.*; @Entity public class Payment { @Id private UUID orderId; private String status; private boolean refundRequired; protected Payment(){} Payment(UUID id,String s){orderId=id;status=s;} public UUID getOrderId(){return orderId;} public String getStatus(){return status;} public boolean isRefundRequired(){return refundRequired;} public void refund(){refundRequired=true;status="REFUND_REQUIRED";} }
